using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool definitions ---

/// <summary>Web search tool that queries a search API and returns results.</summary>
public static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    [Description("Searches the web for the given query and returns a list of result snippets. Use this to find information about a topic.")]
    public static async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_redirect=1";
            var response = await Http.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            // Abstract / AbstractText
            if (response.TryGetProperty("AbstractText", out var abs) &&
                abs.GetString() is { Length: > 0 } abstractText)
            {
                var source = response.TryGetProperty("AbstractSource", out var src)
                    ? src.GetString() : "source";
                results.Add($"[{source}] {abstractText}");
            }

            // RelatedTopics
            if (response.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) &&
                        text.GetString() is { Length: > 0 } snippet)
                    {
                        results.Add(snippet);
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No results found for '{query}'. Try rephrasing.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }
}

/// <summary>Note-taking tool that lets the agent save and retrieve research notes.</summary>
public static class NoteTool
{
    private static readonly List<(string Title, string Content)> Notes = [];

    [Description("Saves a research note with a title and content. Use this to record important findings.")]
    public static string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The note content / finding")] string content)
    {
        Notes.Add((title, content));
        return $"Note saved: \"{title}\" (total notes: {Notes.Count})";
    }

    [Description("Retrieves all saved research notes.")]
    public static string GetNotes()
    {
        if (Notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", Notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Title} ---\n{n.Content}"));
    }
}

// --- Main program ---

Console.WriteLine("🔬 Research Agent");
Console.WriteLine(new string('─', 50));

// Resolve API key and model
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set OPENAI_API_KEY or AZURE_OPENAI_API_KEY environment variable.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// Build the chat client with automatic tool invocation
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Register tools
var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearchTool.SearchWeb),
        AIFunctionFactory.Create(NoteTool.SaveNote),
        AIFunctionFactory.Create(NoteTool.GetNotes),
    ]
};

var systemPrompt = """
    You are a research agent. Your job is to research a topic thoroughly by:
    1. Searching the web for relevant information using the SearchWeb tool.
    2. Saving important findings as notes using the SaveNote tool.
    3. Performing multiple searches to cover different aspects of the topic.
    4. Retrieving your notes with GetNotes and writing a final summary.

    Always save at least 3 notes before summarizing. Be thorough and cite sources
    when available.
    """;

var history = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt)
};

// Get topic from command-line args or prompt interactively
var topic = args.Length > 0
    ? string.Join(' ', args)
    : null;

if (topic is null)
{
    Console.Write("\nEnter a research topic: ");
    topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic))
    {
        Console.WriteLine("No topic provided. Exiting.");
        return;
    }
}

Console.WriteLine($"\nResearching: {topic}\n");

history.Add(new(ChatRole.User,
    $"Research the following topic and provide a comprehensive summary: {topic}"));

// Agent loop — let the model call tools until it produces a final answer
const int maxTurns = 10;
for (var turn = 0; turn < maxTurns; turn++)
{
    var response = await client.GetResponseAsync(history, chatOptions);

    // Append all response messages to history
    foreach (var msg in response.Messages)
        history.Add(msg);

    // If the last message is from the assistant with text content, we're done
    var last = response.Messages[^1];
    if (last.Role == ChatRole.Assistant &&
        last.Text is { Length: > 0 } finalText)
    {
        Console.WriteLine("── Research Summary ─────────────────────────");
        Console.WriteLine(finalText);
        Console.WriteLine("─────────────────────────────────────────────");
        break;
    }
}

Console.WriteLine("\n✅ Research complete.");

