    public static string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The note content / finding")] string content)
    {
        Notes.Add((title, content));
        return $"Note saved: \"{title}\" (total notes: {Notes.Count})";
    }

    [Description("Retrieves all saved research notes.")]
    public static string GetNotes()
    {
        if (Notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", Notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Title} ---\n{n.Content}"));
    }
}

